363.     /// Helper spec function: get the bit value at a specific index from raw bytes.
364.     spec fn bit_at(bytes: Seq<u8>, bit_index: int) -> bool {
365.         let word: int = bit_index / (u8::BITS as int);
366.         let bit: int = bit_index % (u8::BITS as int);
367.         if 0 <= bit_index && word < bytes.len() {
368.             (bytes[word] & (1u8 << bit)) != 0
369.         } else {
370.             false
371.         }
372.     }
