374.     pub open spec fn inv(&self) -> bool {
375.         &&& self@.wf()
376.         &&& self.internal_inv()
377.     }
378. 
379.     /// Invariant: the bitmap's state is well-formed.
380.     pub closed spec fn internal_inv(&self) -> bool {
381.         &&& self.bits.inv()
382.         &&& self@.num_bits > 0
383.         &&& self@.num_bits == self.bits@.len() * (u8::BITS as int)
384.         &&& self@.num_bits < u32::MAX as int
385.         &&& self@.wf()  // set_bits only contains valid indices
386.         &&& self@.set_bits.finite()  // set_bits is finite (required for len())
387.         &&& self@.usage() <= self@.num_bits
388.         &&& self.number_of_bits as int == self@.num_bits
389.         &&& self.usage as int == self@.usage()
390.         &&& self.next_free as int <= self@.num_bits
391.     }
392. }
